"""Build the QGIS demo-upload project from frozen offline sources.

Offline and deterministic: every input lives in ``sources/`` (see
``sources/attribution.txt``), so rebuilds need no network. Steps:

- ``gpkg``:    ``demo-upload.gpkg`` with 3 file layers —
               world_countries (EPSG:4326), world_rivers (EPSG:3857),
               world_places (EPSG:3395).
- ``postgis``: ``postgis/init.sql`` seeding world_lakes (EPSG:4269) and
               us_states (EPSG:5070) via GDAL PGDUMP (INSERTs, no live DB).
- ``qgz``:     ``demo-upload.qgz`` (project CRS EPSG:3857) with 5 styled
               layers — 3 GPKG + 2 PostGIS — built with headless PyQGIS
               (``QT_QPA_PLATFORM=offscreen``), the same pattern as
               ``tests/fixtures/qgis/capture.py``.

Usage: ``python3 scripts/build.py [--step gpkg|postgis|qgz|all]``.
Idempotent: outputs are deleted before they are regenerated.
"""

import argparse
import os
import shutil
import subprocess
import sys
import tempfile

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
SOURCES = os.path.join(ROOT, "sources")
GPKG = os.path.join(ROOT, "demo-upload.gpkg")
QGZ = os.path.join(ROOT, "demo-upload.qgz")
POSTGIS_DIR = os.path.join(ROOT, "postgis")
INIT_SQL = os.path.join(POSTGIS_DIR, "init.sql")

# (source file, gpkg layer, target SRS, kept attributes, geometry type)
GPKG_LAYERS = [
    ("ne_countries.geojson", "world_countries", "EPSG:4326",
     "ADMIN,ADM0_A3,NAME,CONTINENT,POP_EST", "MULTIPOLYGON"),
    ("ne_rivers.geojson", "world_rivers", "EPSG:3857", "name", None),
    ("ne_places.geojson", "world_places", "EPSG:3395",
     "NAME,ADM0NAME,POP_MAX", None),
]

# (source file, table, target SRS, kept attributes, geometry type)
POSTGIS_TABLES = [
    ("ne_lakes.geojson", "world_lakes", 4269, "name", "POLYGON"),
    ("us_states.geojson", "us_states", 5070, "STATEFP,STUSPS,NAME",
     "MULTIPOLYGON"),
]

INIT_HEADER = """-- Generated by scripts/build.py (T-t3x.2). Do not edit: re-run the script.
-- Seeds the demo-upload PostGIS database (postgis/docker-compose.yml).
CREATE EXTENSION IF NOT EXISTS postgis;
"""


def run(cmd):
    print("+ " + " ".join(cmd), flush=True)
    subprocess.run(cmd, check=True)


def build_gpkg():
    if os.path.exists(GPKG):
        os.remove(GPKG)
    for i, (src, layer, srs, select, geom_type) in enumerate(GPKG_LAYERS):
        cmd = ["ogr2ogr", "-f", "GPKG"]
        if i > 0:
            cmd.append("-update")
        cmd += [GPKG, os.path.join(SOURCES, src),
                "-nln", layer, "-t_srs", srs, "-select", select]
        if geom_type:
            cmd += ["-nlt", geom_type]
        run(cmd)


def build_postgis():
    os.makedirs(POSTGIS_DIR, exist_ok=True)
    parts = [INIT_HEADER]
    with tempfile.TemporaryDirectory() as tmp:
        for src, table, srid, select, geom_type in POSTGIS_TABLES:
            dump = os.path.join(tmp, table + ".sql")
            run(["ogr2ogr", "-f", "PGDUMP", dump,
                 os.path.join(SOURCES, src),
                 "-nln", table, "-t_srs", f"EPSG:{srid}",
                 "-select", select, "-nlt", geom_type,
                 "-lco", f"SRID={srid}", "-lco", "SCHEMA=public"])
            with open(dump, encoding="utf-8") as fh:
                for line in fh:
                    # Fresh compose databases already own "public".
                    if line.startswith("CREATE SCHEMA"):
                        continue
                    parts.append(line)
    with open(INIT_SQL, "w", encoding="utf-8") as fh:
        fh.writelines(parts)


PG_HOST, PG_PORT, PG_DB, PG_USER, PG_PASSWORD = (
    "localhost", "5432", "demo", "demo", "demo")


def pg_uri(table, geom, srid, geom_type):
    return ("dbname='%s' host=%s port=%s user='%s' password='%s' "
            "sslmode=disable key='ogc_fid' srid=%d type=%s "
            "table=\"public\".\"%s\" (%s)" % (
                PG_DB, PG_HOST, PG_PORT, PG_USER, PG_PASSWORD,
                srid, geom_type, table, geom))


def build_qgz():
    os.environ.setdefault("QT_QPA_PLATFORM", "offscreen")
    from qgis.core import (  # noqa: E402
        QgsApplication,
        QgsCategorizedSymbolRenderer,
        QgsCoordinateReferenceSystem,
        QgsFillSymbol,
        QgsGraduatedSymbolRenderer,
        QgsLineSymbol,
        QgsMarkerSymbol,
        QgsProject,
        QgsRendererCategory,
        QgsRendererRange,
        QgsSingleSymbolRenderer,
        QgsVectorLayer,
    )
    from qgis.PyQt.QtGui import QColor  # noqa: E402

    QgsApplication.setPrefixPath("/usr", True)
    app = QgsApplication([], False)
    QgsApplication.initQgis()
    try:
        project = QgsProject.instance()
        project.clear()
        project.setCrs(QgsCoordinateReferenceSystem("EPSG:3857"))
        project.setTitle("demo-upload")

        def ogr_layer(gpkg_layer):
            lyr = QgsVectorLayer(
                "demo-upload.gpkg|layername=" + gpkg_layer,
                gpkg_layer, "ogr")
            assert lyr.isValid(), f"GPKG layer invalid: {gpkg_layer}"
            return lyr

        def single_fill(color, outline, width):
            sym = QgsFillSymbol.createSimple(
                {"color": color, "outline_color": outline,
                 "outline_width": width})
            return QgsSingleSymbolRenderer(sym)

        def single_line(color, width):
            sym = QgsLineSymbol.createSimple(
                {"color": color, "width": width})
            return QgsSingleSymbolRenderer(sym)

        countries = ogr_layer("world_countries")
        countries.setRenderer(single_fill(
            "178,223,138,255", "60,90,60,255", "0.26"))
        rivers = ogr_layer("world_rivers")
        rivers.setRenderer(single_line("31,120,180,255", "0.6"))
        places = ogr_layer("world_places")
        apply_graduated(places, QgsMarkerSymbol, QgsRendererRange,
                        QgsGraduatedSymbolRenderer)
        lakes = QgsVectorLayer(
            pg_uri("world_lakes", "wkb_geometry", 4269, "POLYGON"),
            "world_lakes", "postgres")
        # The PostGIS layers are invalid at build time (no database), so
        # QGIS cannot resolve their CRS from the server and would write an
        # empty <srs> (srid 0). With no CRS the project CRS (EPSG:3857) is
        # assumed on open: 5070 metres land near Null Island, which is the
        # us_states-over-West-Africa misprojection. Pin the CRS explicitly
        # so the .qgs carries it offline.
        lakes.setCrs(QgsCoordinateReferenceSystem("EPSG:4269"))
        lakes.setRenderer(single_fill(
            "158,202,225,255", "40,80,120,255", "0.26"))
        states = QgsVectorLayer(
            pg_uri("us_states", "wkb_geometry", 5070, "MULTIPOLYGON"),
            "us_states", "postgres")
        states.setCrs(QgsCoordinateReferenceSystem("EPSG:5070"))
        apply_categorized(states, QgsFillSymbol, QgsRendererCategory,
                          QgsCategorizedSymbolRenderer, QColor)

        # First layer paints on top.
        project.addMapLayers([places, rivers, lakes, states, countries])
        assert project.write(QGZ), f"project write failed: {QGZ}"
        print(f"wrote {QGZ}", flush=True)
    finally:
        QgsApplication.exitQgis()
        app.exit()


def apply_graduated(layer, MarkerSymbol, RendererRange, GraduatedRenderer):
    from qgis.PyQt.QtGui import QColor
    field = "POP_MAX"
    idx = layer.fields().indexOf(field)
    values = [f[idx] for f in layer.getFeatures() if f[idx] is not None]
    lo, hi = min(values), max(values)
    n = 5
    step = (hi - lo) / n
    ranges = []
    for i in range(n):
        lower = lo + i * step
        upper = hi if i == n - 1 else lo + (i + 1) * step
        size = 2.0 + i * 1.2
        sym = MarkerSymbol.createSimple(
            {"name": "circle",
             "color": QColor(254 - i * 22, 224 - i * 34, 144, 255).name(),
             "size": str(size),
             "outline_color": "80,40,20,255",
             "outline_width": "0.2"})
        ranges.append(RendererRange(
            lower, upper, sym,
            f"{int(lower):,} - {int(upper):,}"))
    layer.setRenderer(GraduatedRenderer(field, ranges))


def apply_categorized(layer, FillSymbol, RendererCategory,
                      CategorizedRenderer, QColor):
    from qgis.core import QgsVectorLayer as VL
    field = "STUSPS"
    # Layer may be invalid offline (no PostGIS); fall back to the frozen
    # source so the categorized style is still fully defined in the .qgz.
    if not layer.isValid():
        probe = VL(os.path.join(SOURCES, "us_states.geojson"), "probe", "ogr")
        assert probe.isValid(), "us_states source invalid"
        idx = probe.fields().indexOf(field)
        values = sorted({f[idx] for f in probe.getFeatures()})
    else:
        idx = layer.fields().indexOf(field)
        values = sorted(layer.dataProvider().uniqueValues(idx))
    cats = []
    for i, value in enumerate(values):
        hue = (i * 360 // len(values)) % 360
        color = QColor.fromHsv(hue, 150, 220).name()
        sym = FillSymbol.createSimple(
            {"color": color, "outline_color": "60,60,60,255",
             "outline_width": "0.2"})
        cats.append(RendererCategory(value, sym, str(value)))
    layer.setRenderer(CategorizedRenderer(field, cats))


STEPS = {"gpkg": build_gpkg, "postgis": build_postgis, "qgz": build_qgz}


def main(argv):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--step", choices=["gpkg", "postgis", "qgz", "all"],
                        default="all")
    args = parser.parse_args(argv)
    steps = list(STEPS) if args.step == "all" else [args.step]
    if "qgz" in steps:
        # Relative GPKG sources resolve against the project directory.
        os.chdir(ROOT)
    for step in steps:
        STEPS[step]()
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
